$script:Lang='en'
function Set-Language([string]$code){
    if(!$Strings.ContainsKey($code)){$code='en'}
    $script:Lang=$code
}
function Get-DefaultLanguage {
    $c=[Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName
    if($Strings.ContainsKey($c)){return $c}
    return 'en'
}
function T([string]$key){
    $s=$Strings[$script:Lang][$key]
    if($null -eq $s){$s=$Strings['en'][$key]}
    if($null -eq $s){return $key}
    $s=$s.Replace('\n',"`n")
    if($args.Count){return [string]::Format($s,[object[]]$args)}
    return $s
}
